const tableRows = (chunk) => {
const rows = []
for (const line of chunk.split('\n')) {
const t = line.trim()
if (!t.startsWith('|')) continue
const cells = t.replace(/^\||\|$/g, '').split('|').map((s) => s.trim())
if (cells.length < 2) continue
if (/^-{2,}$/.test(cells[0]) || cells[0] === '' || cells[0] === '从' || cells[0] === 'ID') continue
rows.push(cells)
}
return rows
}

