i = if (lineEnd < 0) text.length else lineEnd
continue
}
if (ch == ';' || ch == '\n' || ch == '\r') {
flush()
i += 1
continue
}
if (ch == '&' || ch == '|') {
flush()
i += if (i + 1 < text.length && text[i + 1] == ch) 2 else 1
