return ParsedCommand(segments.filter { it.isNotBlank() }, unparsed)
}
/** 反引号段结束位置；`\`` 转义不算结束。返回 -1 = 未闭合。 */
private fun backtickEnd(text: String, from: Int): Int {
var i = from
while (i < text.length) {
if (text[i] == '\\') {
i += 2
continue
}
if (text[i] == '`') return i
i += 1
}
return -1
}
/** `$(` 的配对 `)` 位置（内部引号与嵌套括号都计入）。返回 -1 = 未闭合。 */
private fun parenEnd(text: String, from: Int): Int {
var depth = 1
var i = from
while (i < text.length) {
val ch = text[i]
if (ch == '\\') {
i += 2
continue
}
if (ch == '\'' || ch == '"') {
val quote = ch
i += 1
while (i < text.length) {
if (quote == '"' && text[i] == '\\') {
i += 2
continue
}
if (text[i] == quote) break
i += 1
}
i += 1
continue
}
if (ch == '(') {
depth += 1
} else if (ch == ')') {
depth -= 1
if (depth == 0) return i
}
i += 1
}
