if (quote == '"' && text[j] == '\\') {
j += 2
continue
}
if (text[j] == quote) break
j += 1
}
if (j >= text.length) {
out.append(' ')
i = text.length
continue
}
if (inFirstWord) out.append(text, (if (ansiC) i + 1 else i) + 1, j) else out.append(' ')
